          .attr('r', r)
          .attr('fill', d.tier === 'Access' ? '#e0f2fe' : '#f3e8ff')
          .attr('stroke', d.tier === 'Access' ? '#2563eb' : '#7c3aed')
          .attr('stroke-width', 2);
      }
    });

    nodeGroup.append('text')
      .attr('y', d => {
        const r = d.degree >= 5 ? 32 : 26;
        return d.type === 'infrastructure' ? r * 0.8 + 16 : r + 18;
      })
      .attr('text-anchor', 'middle')
      .text(d => d.label)
      .attr('font-size', d => d.degree >= 5 ? '16px' : '14px')
      .attr('font-weight', d => d.degree >= 5 ? '700' : '500')
      .attr('fill', '#0f172a');

    nodeGroup.filter(d => d.degree >= 5)
      .append('text')
      .attr('y', -45)
      .attr('text-anchor', 'middle')
      .text(d => `HOTSPOT: ${d.degree} links`)
      .attr('font-size', '12px')
      .attr('font-weight', 'bold')
      .attr('fill', '#e11d48');

  </script>
</body>
</html>
"""

html_out = html_template.replace('__NODES__', json.dumps(nodes)).replace('__EDGES__', json.dumps(edges))

with open('/app/output/chart.html', 'w') as f:
    f.write(html_out)
